"use strict";
const express = require("express");
const path = require("node:path");
const app = express();
for (const fichier of ["index.html", "app.js", "styles.css"]) {
  app.get(`/${fichier}`, (_req, res) => res.sendFile(path.join(__dirname, fichier)));
}
app.get("/api/notes", (_req, res) => res.json({ donnees: [{ id: 1, titre: "Première note" }, { id: 2, titre: "Deuxième note" }] }));
app.listen(3000, () => console.log("http://localhost:3000/index.html"));

"use strict";
const bouton = document.querySelector("#charger");
const etat = document.querySelector("#etat");
const liste = document.querySelector("#liste-notes");
bouton.addEventListener("click", async () => {
  etat.textContent = "Chargement…";
  try {
    const reponse = await fetch("/api/notes");
    if (!reponse.ok) throw new Error(`HTTP ${reponse.status}`);
    const donnees = await reponse.json();
    liste.replaceChildren(...donnees.donnees.map(note => { const li = document.createElement("li"); li.textContent = note.titre; return li; }));
    etat.textContent = `${donnees.donnees.length} note(s)`;
  } catch (erreur) { etat.textContent = `Impossible de charger : ${erreur.message}`; }
});
